%[text] %[text:anchor:T_C33FC1A9] # Solving the Timoshenko beam problem using sparse matrices and page-wise implementation
%[text:tableOfContents]{"heading":"Table of Contents"}
%[text] In this appendix it is demonstrated how to leverage [`sparse`](https://www.mathworks.com/help/matlab/ref/sparse.html)-matrices and [page-wise operations](https://blogs.mathworks.com/loren/2021/01/14/paged-matrix-functions/) in [MATLAB](https://www.mathworks.com/products/matlab.html)® to speed-up the computation, assembly and solution of the linear equation systems resulting from the discretization of the [Timoshenko beam](https://en.wikipedia.org/wiki/Timoshenko%E2%80%93Ehrenfest_beam_theory) *Boundary Value Problem* (BVP).
%[text] 
%[text] **Author: Andreas Apostolatos, PhD (aapostol@mathworks.com)**
%[text] **Date: 10.06.2026**
%%
%[text] %[text:anchor:H_9B9D2555] ## Preamble
clc;
clear;
close all;
%%
%[text] %[text:anchor:H_4AD2C524] ## **Problem parameters**
%[text] %[text:anchor:H_56C3014F] ### Geometric parameters
%[text] %[text:anchor:M_1380FB13] Thickness \[m\]
propStr.t = 10^(-1); %[control:slider:2abb]{"position":[17,19]}
%[text] Width \[m\]
propStr.b = .1;
%[text] Height \[m\]
propStr.A = propStr.b*propStr.t;
%[text] X-coordinate at the left end of the beam \[m\]
X0 = 0;
%[text] Y-coordinate at the right end of the beam \[m\]
XL = 4;
%[text] %[text:anchor:H_D282B28D] ### Material paramerters
%[text] Distributed load along the beam's length \[N/m^2\]
propStr.qBar = -1e4*(propStr.t)^3;
%[text] Distributed moment along the beam's length \[N/m\]
propStr.mBar = 0;
%[text] Boundary force \[N\]
propStr.Q = 0;
%[text] Boundary moment \[Nm\]
propStr.M = 0;
%[text] Young's modulus \[N/m^2\]
propStr.E = 1e7;
%[text] Poisson ratio \[dimensionless\]
propStr.nu = 0.3;
%[text] Moment of inertia \[m^4\]
propStr.I = propStr.b*(propStr.t^3)/12;
%[text] Shear modulus (connected to epsilon\_12 = E/(1+nu)) \[N/m^2\]
propStr.G = propStr.E/(2*(1 + propStr.nu));
%[text] Shear correction factor \[dimensionless\]
propStr.alpha = 5/6;
%%
%[text] %[text:anchor:H_465616C8] ## Analytical solution
%[text] %[text:anchor:H_D455EF05] ### Initialization of auxiliary variables
syms wEx(X) betaEx(X) QEx(X) Lsym qsym Gsym Acs alphaScf Aqsym Esym Isym
%[text] %[text:anchor:H_86B7747F] ### Analytical solution with respect to the vertical deflection
wEx(X) = (qsym*Lsym*X-qsym*X^2/2)/Gsym/(Aqsym) - ...
    (-qsym*X^4/24+qsym*Lsym*X^3/6-qsym*Lsym^2*X^2/4)/Esym/Isym;
%[text] %[text:anchor:H_BDF2CE9F] ### Analytical solution with respect to the cross-sectional rotation
%[text] Get the analytical solution of the rotational field by leveraging the Partial Differential Equation (PDE) of the problem and the functions of the [Symbolic Math Toolbox](https://www.mathworks.com/products/symbolic.html)™ in [MATLAB](https://www.mathworks.com/products/matlab.html)®
%[text] $\\beta(X) = \\int\_{0}^L - \\frac{1}{\\alpha G A}\\overline{Q} - \\frac{\\text{d}^2 w}{\\text{d} x^2} \\: \\text{d}x \\quad \\quad (1)$
betaEx(X) = int(-1/(propStr.alpha*propStr.G*propStr.A)*propStr.qBar - ...
    diff(diff(wEx, X), X));
%[text] %[text:anchor:H_4FF8DB3D] ### Evaluation of the expressions for the given geometric and material parameters
QEx(X) = alphaScf*Gsym*Acs*(diff(wEx(X), X, 1) + betaEx(X));
%[text] %[text:anchor:H_466D9AB3] ### Evaluation of the expressions for the given geometric and material parameters
wEx(X) = subs(wEx,{Lsym, qsym, Gsym, Esym, Isym, Aqsym}, ...
    {XL, propStr.qBar, propStr.G, propStr.E, propStr.b*(propStr.t^3)/12, ...
    propStr.alpha*propStr.b*propStr.t});
betaEx(X) = subs(betaEx,{Lsym, qsym, Gsym, Esym, Isym, Aqsym}, ...
    {XL, propStr.qBar, propStr.G, propStr.E, propStr.b*(propStr.t^3)/12, ...
    propStr.alpha*propStr.b*propStr.t});
QEx(X) = subs(QEx, {alphaScf, Gsym, Acs, Lsym, qsym, Gsym, Esym, Isym, Aqsym}, ...
    {propStr.alpha, propStr.G, propStr.A,XL, propStr.qBar, propStr.G, propStr.E, ...
    propStr.b*(propStr.t^3)/12, propStr.alpha*propStr.b*propStr.t});
%%
%[text] %[text:anchor:H_6AC683FB] ## Verification of the the accuracy of the page-wise implementation
%[text] %[text:anchor:H_E1F8EC05] ### Generation of an one-dimensional mesh using linear two-noded elements
%[text] %[text:anchor:H_D86CE7B1] #### Mesh generation
numElL1 = 7;
mshL1 = generateLinearMeshOnLine(X0, XL, numElL1);
numNodesL1 = numel(mshL1.nodes);
%[text] %[text:anchor:H_1811338E] #### **Definition of the boundary conditions**
freeDOFsL1 = 1:2*numNodesL1;
numDOFsL1 = 2*numNodesL1;
homDOFsL1 = 1:2;
[~, idxL1] = ismember(homDOFsL1, freeDOFsL1);
freeDOFsL1(idxL1) = [];
%[text] %[text:anchor:H_83EA3752] #### Mesh plot
plotMesh1d(mshL1); %[output:69c43732]
xlabel("$X$", Interpreter="latex") %[output:69c43732]
ylabel("$Y$", Interpreter="latex") %[output:69c43732]
title("Finite Element discretization of the beam using " + ... %[output:group:4cd1723b] %[output:69c43732]
    "two-noded linear elements") %[output:group:4cd1723b] %[output:69c43732]
%[text] %[text:anchor:H_42F19D85] ### Generation of an one-dimensional mesh using quadratic three-noded elements
%[text] %[text:anchor:H_C249145B] #### Mesh generation
mshL2 = generateQuadraticMeshOnLine(mshL1);
numNodesL2 = numel(mshL2.nodes);
%[text] %[text:anchor:H_584A7452] #### **Define the boundary conditions of the problem for the mesh with the quadratic finite elements**
freeDOFsL2 = 1:2*numNodesL2;
numDOFsL2 = 2*numNodesL2;
homDOFsL2 = 1:2;
[~, idxL2] = ismember(homDOFsL2, freeDOFsL2);
freeDOFsL2(idxL2) = [];
%[text] %[text:anchor:H_69404B7A] #### Mesh plot
plotMesh1d(mshL2) %[output:97d3a0e4]
xlabel("$X$", Interpreter="latex") %[output:97d3a0e4]
ylabel("$Y$", Interpreter="latex") %[output:97d3a0e4]
title("Finite Element discretization of the beam using " + ... %[output:group:2d1c2783] %[output:97d3a0e4]
    "three-noded quadratic elements") %[output:group:2d1c2783] %[output:97d3a0e4]
%[text] %[text:anchor:H_9A5E444E] ### Computation of the master stiffness matrix and consistent nodal force vector with and without the page-wise implementation
%[text] %[text:anchor:H_224FB01B] #### Standard implementation for the one-dimenstional linear two-noded finite elements
computeStiffMatrixandForceVectorTB = ...
    @computeElementStiffMatrixandForceVectorTimoshenkoBeam;
computeBasisFunctionsAndDerivs = ...
    @computeLinearBasisFunctionsAndFirstDerivatives;
dummyInp = 'undefined';
[KL1, FL1] = computeMasterStiffMatrixandForceVectorTimoshenkoBeam ...
    (mshL1, computeStiffMatrixandForceVectorTB, computeBasisFunctionsAndDerivs, ...
    dummyInp, propStr);
%[text] %[text:anchor:H_F368DA59] #### Page-wise implementation using sparse matrices for the one-dimenstional linear two-noded finite elements
computeBasisFunctionsAndDerivs = @computeLinearBasisFunctionsAndFirstDerivatives;
computeStiffMatrixandForceVectorTB = 'undefined';
dummyInp = 'undefined';
[KPageWiseL1, FPageWiseL1] = ...
    computeMasterStiffMatrixandForceVectorTimoshenkoBeamPageWise ...
    (mshL1, computeStiffMatrixandForceVectorTB, computeBasisFunctionsAndDerivs, ...
    dummyInp, propStr);
%[text] %[text:anchor:H_004CA707] #### Standard implementation for the one-dimenstional linear two-noded finite elements
computeStiffMatrixandForceVectorTB = ...
    @computeElementStiffMatrixandForceVectorTimoshenkoBeam;
computeBasisFunctionsAndDerivs = ...
    @computeQuadraticBasisFunctionsAndFirstDerivatives;
dummyInp = 'undefined';
[KL2, FL2] = computeMasterStiffMatrixandForceVectorTimoshenkoBeam ...
    (mshL2, computeStiffMatrixandForceVectorTB, computeBasisFunctionsAndDerivs, ...
    dummyInp, propStr);
%[text] %[text:anchor:H_F684D37E] #### Page-wise implementation using sparse matrices using sparse matrices for the one-dimenstional linear two-noded finite elements
computeBasisFunctionsAndDerivs = ...
    @computeQuadraticBasisFunctionsAndFirstDerivatives;
computeStiffMatrixandForceVectorTB = 'undefined';
dummyInp = 'undefined';
[KPageWiseL2, FPageWiseL2] = ...
    computeMasterStiffMatrixandForceVectorTimoshenkoBeamPageWise ...
    (mshL2, computeStiffMatrixandForceVectorTB, computeBasisFunctionsAndDerivs, ...
    dummyInp, propStr);
%[text] %[text:anchor:H_4F637DD3] ### Solution of the discrete linear equation system
%[text] %[text:anchor:H_9CBE133D] #### Standard implementation for the one-dimenstional linear two-noded finite elements
uL1 = zeros(numDOFsL1, 1);
uL1(freeDOFsL1, 1) = KL1(freeDOFsL1, freeDOFsL1)\FL1(freeDOFsL1);
%[text] %[text:anchor:H_197B9102] #### Page-wise implementation using sparse matrices for the one-dimenstional linear two-noded finite elements
uPageWiseL1 = zeros(numDOFsL1, 1);
uPageWiseL1(freeDOFsL1, 1) = ...
    KPageWiseL1(freeDOFsL1, freeDOFsL1)\FPageWiseL1(freeDOFsL1);
%[text] %[text:anchor:H_D19598A7] #### Standard implementation for the one-dimenstional quadratic three-noded finite elements
uL2 = zeros(numDOFsL2, 1);
uL2(freeDOFsL2, 1) = KL2(freeDOFsL2, freeDOFsL2)\FL2(freeDOFsL2);
[nodesL2, idx] = sort(mshL2.nodes);
wL2 = uL2(1:2:end, 1);
betaL2 = uL2(2:2:end, 1);
%[text] %[text:anchor:H_6E86BA1D] #### Page-wise implementation using sparse matrices for the one-dimenstional quadratic three-noded finite elements
uPageWiseL2 = zeros(numDOFsL2, 1);
uPageWiseL2(freeDOFsL2, 1) = ...
    KPageWiseL2(freeDOFsL2, freeDOFsL2)\FPageWiseL2(freeDOFsL2);
wPageWiseL2 = uPageWiseL2(1:2:end, 1);
betaPageWise_L2 = uPageWiseL2(2:2:end, 1);
%%
%[text] %[text:anchor:H_79B4D533] ### Postprocessing the discrete solutions
%[text] %[text:anchor:H_C86C7B30] #### Visualization of the deformed configuration
plot(mshL1.nodes, uL1(1:2:end, 1), '-bo', LineWidth=2) %[output:2ffb6afe]
hold on; %[output:2ffb6afe]
plot(mshL1.nodes, uPageWiseL1(1:2:end, 1), '-bv', LineWidth=2); %[output:2ffb6afe]
plot(nodesL2, wL2(idx), '-ro', LineWidth=2); %[output:2ffb6afe]
plot(nodesL2, wPageWiseL2(idx), '-rv', LineWidth=2); %[output:2ffb6afe]
fplot(wEx, [X0 XL], '-k', LineWidth=2); %[output:2ffb6afe]
hold off; %[output:2ffb6afe]
grid on; %[output:2ffb6afe]
legend("L1", "L1 page-wise", "L2", "L2 page-wise", "analytical", ... %[output:2ffb6afe]
    Location="best") %[output:2ffb6afe]
title("Deformed configuration of the beam") %[output:2ffb6afe]
%[text] %[text:anchor:H_C3B253AE] #### Visualization of the cross-sectional rotation field
plot(mshL1.nodes, uL1(2:2:end, 1), '-bo', LineWidth=2) %[output:1e7f9334]
hold on; %[output:1e7f9334]
plot(mshL1.nodes, uPageWiseL1(2:2:end, 1), '-bv', LineWidth=2); %[output:1e7f9334]
plot(nodesL2, betaL2(idx), '-ro', LineWidth=2); %[output:1e7f9334]
plot(nodesL2, betaPageWise_L2(idx), '-rv', LineWidth=2); %[output:1e7f9334]
fplot(betaEx, [X0 XL], '-k', LineWidth=2); %[output:1e7f9334]
hold off; %[output:1e7f9334]
grid on; %[output:1e7f9334]
legend("L1", "L1 page-wise", "L2", "L2 page-wise", "analytical", ... %[output:1e7f9334]
    Location="best") %[output:1e7f9334]
title("Cross-sectional rotation of the beam") %[output:1e7f9334]
%%
%[text] %[text:anchor:H_96CEE74F] ## Runtime performance using sparse matrices and page-wise implementation of the linear two-noded finite elements
%[text] %[text:anchor:H_6CEB6F4C] ### Initialize auxiliary variables
numRef = 1000;
stp = 3;
runtimePerformanceL1 = zeros(ceil(numRef/stp), 2);
numDOFsL1 = zeros(ceil(numRef/stp), 1);
%[text] %[text:anchor:H_59D283CD] ### Loop over all the refinement levels
for ii = 1:stp:numRef
%[text] %[text:anchor:H_DB574135] #### Generation of the the finite element mesh
    numElL1Ref = ii;
    mshL1Ref = generateLinearMeshOnLine(X0, XL, numElL1Ref);
    numNodesL1Ref = numel(mshL1Ref.nodes);
    numDOFsL1(ceil(ii/stp)) = 2*numNodesL1Ref;
%[text] %[text:anchor:H_C8F28FFB] #### Definition of the Dirichlet boundary conditions
    freeDOFsL1Ref = 1:2*numNodesL1Ref;
    homDOFsL1Ref = 1:2;
    [~, idxL1Ref] = ismember(homDOFsL1Ref, freeDOFsL1Ref);
    freeDOFsL1Ref(idxL1Ref) = [];
%[text] %[text:anchor:H_CB270036] #### Solution of the discrete problem using the standard Finite Element implementation
%[text] %[text:anchor:H_65A02DDE] ... starting the timer
    tic;
%[text] %[text:anchor:H_8CE4850E] ... computing of the stiffness matrix and consistent nodal force vector for the one-dimensional two-noded linear mesh
    computeStiffMatrixandForceVectorTB = ...
        @computeElementStiffMatrixandForceVectorTimoshenkoBeam;
    computeBasisFunctionsAndDerivs = ...
        @computeLinearBasisFunctionsAndFirstDerivatives;
    dummyInp = 'undefined';
    [K, F] = computeMasterStiffMatrixandForceVectorTimoshenkoBeam ...
        (mshL1Ref, computeStiffMatrixandForceVectorTB, ...
        computeBasisFunctionsAndDerivs, dummyInp, propStr);
%[text] %[text:anchor:H_5404BB62] ... solving the discrete linear equation system
    [~] = K(freeDOFsL1Ref, freeDOFsL1Ref)\F(freeDOFsL1Ref);
%[text] %[text:anchor:H_8E98BAEF] ... stopping the timer
    runtimePerformanceL1((ceil(ii/stp)), 1) = toc;
%[text] %[text:anchor:H_02283F3F] #### Solution of the discrete problem using the page-wise Finite Element implementation with sparse matrices
%[text] %[text:anchor:H_D1E01B18] ... starting the timer
    tic;
%[text] %[text:anchor:H_16B83382] ... computing of the stiffness matrix and consistent nodal force vector for the one-dimensional two-noded linear mesh
    computeBasisFunctionsAndDerivs = @computeLinearBasisFunctionsAndFirstDerivatives;
    computeStiffMatrixandForceVectorTB = 'undefined';
    dummyInp = 'undefined';
    [K, F] = computeMasterStiffMatrixandForceVectorTimoshenkoBeamPageWise ...
        (mshL1Ref, computeStiffMatrixandForceVectorTB, computeBasisFunctionsAndDerivs, ...
        dummyInp, propStr);
%[text] %[text:anchor:H_0F0F778B] ... solving the discrete linear equation system
    [~] = K(freeDOFsL1Ref, freeDOFsL1Ref)\F(freeDOFsL1Ref);
%[text] %[text:anchor:H_0DEE95E4] ... stopping the timer
    runtimePerformanceL1((ceil(ii/stp)), 2) = toc;
%[text] 
end
%%
%[text] %[text:anchor:H_0DA5D19D] ### Display of the runtime performance comparison between the standard and the page-wise implementation
loglog(numDOFsL1, runtimePerformanceL1, LineWidth=2); %[output:05db622a]
legend("standard", "page-wise", Location="best") %[output:05db622a]
grid on; %[output:05db622a]
xlabel("No. DOFs") %[output:05db622a]
ylabel("Runtime (s)") %[output:05db622a]
title(["Comparison of the runtime performance between the standard and the", ... %[output:group:307d8af9] %[output:05db622a]
    "page-wise implementation for the one-dimensional linear elements", ""]) %[output:group:307d8af9] %[output:05db622a]
%%
%[text] %[text:anchor:H_B1B1F06A] ## Runtime performance using sparse matrices and page-wise implementation of the quadratic three-noded finite elements
%[text] %[text:anchor:H_5461E352] ### Initialize auxiliary variables
numRef = 1000;
stp = 9;
runtimePerformanceL2 = zeros(ceil(numRef/stp), 2);
numDOFsL2 = zeros(ceil(numRef/stp), 1);
%[text] %[text:anchor:H_BCBAF50C] ### Loop over all the refinement levels
for ii = 1:stp:numRef
%[text] %[text:anchor:H_80FBA6AC] #### Generation of the the finite element mesh
    numElL1Ref = ii;
    mshL1Ref = generateLinearMeshOnLine(X0, XL, numElL1Ref);
    numNodesL1Ref = numel(mshL1Ref.nodes);
    mshL2Ref = generateQuadraticMeshOnLine(mshL1Ref);
    numNodesL2Ref = numel(mshL2Ref.nodes);
    numDOFsL2(ceil(ii/stp), 1) = 2*numNodesL2Ref;
%[text] %[text:anchor:H_EE55F8EA] #### Definition of the Dirichlet boundary conditions
    freeDOFsL2Ref = 1:2*numNodesL2Ref;
    homDOFsL2Ref = 1:2;
    [~, idxL2Ref] = ismember(homDOFsL2Ref, freeDOFsL2Ref);
    freeDOFsL2Ref(idxL2Ref) = [];
%[text] %[text:anchor:H_66DF1605] #### Solution of the discrete problem using the page-wise Finite Element implementation with sparse matrices
%[text] %[text:anchor:H_65A02DDE] ... starting the timer
    tic;
%[text] %[text:anchor:H_8CE4850E] ... computing of the stiffness matrix and consistent nodal force vector for the one-dimensional two-noded linear mesh
    computeStiffMatrixandForceVectorTB = ...
        @computeElementStiffMatrixandForceVectorTimoshenkoBeam;
    computeBasisFunctionsAndDerivs = ...
        @computeQuadraticBasisFunctionsAndFirstDerivatives;
    dummyInp = 'undefined';
    [K, F] = computeMasterStiffMatrixandForceVectorTimoshenkoBeam ...
        (mshL2Ref, computeStiffMatrixandForceVectorTB, computeBasisFunctionsAndDerivs, ...
        dummyInp, propStr);
%[text] %[text:anchor:H_5404BB62] ... solving the discrete linear equation system
    [~] = K(freeDOFsL2Ref, freeDOFsL2Ref)\F(freeDOFsL2Ref);
%[text] %[text:anchor:H_8E98BAEF] ... stopping the timer
    runtimePerformanceL2((ceil(ii/stp)), 1) = toc;
%[text] %[text:anchor:H_B8709CD0] #### Solution of the discrete problem using the standard Finite Element implementation
%[text] %[text:anchor:H_D1E01B18] ... starting the timer
    tic;
%[text] %[text:anchor:H_16B83382] ... computing of the stiffness matrix and consistent nodal force vector for the one-dimensional two-noded linear mesh
    computeBasisFunctionsAndDerivs = ...
        @computeQuadraticBasisFunctionsAndFirstDerivatives;
    computeStiffMatrixandForceVectorTB = 'undefined';
    dummyInp = 'undefined';
    [K, F] = computeMasterStiffMatrixandForceVectorTimoshenkoBeamPageWise ...
        (mshL2Ref, computeStiffMatrixandForceVectorTB, computeBasisFunctionsAndDerivs, ...
        dummyInp, propStr);
%[text] %[text:anchor:H_0F0F778B] ... solving the discrete linear equation system
    [~] = K(freeDOFsL2Ref, freeDOFsL2Ref)\F(freeDOFsL2Ref);
%[text] %[text:anchor:H_0DEE95E4] ... stopping the timer
    runtimePerformanceL2((ceil(ii/stp)), 2) = toc;
%[text] 
end
%%
%[text] %[text:anchor:H_971FCB50] ### Display of the runtime performance comparison between the standard and the page-wise implementation
loglog(numDOFsL2, runtimePerformanceL2, LineWidth=2); %[output:78e6c7f7]
legend("standard", "page-wise", Location="best") %[output:78e6c7f7]
grid on; %[output:78e6c7f7]
xlabel("No. elements") %[output:78e6c7f7]
ylabel("Runtime (s)") %[output:78e6c7f7]
title(["Comparison of the runtime performance between the standard and the", ... %[output:group:4452bca0] %[output:78e6c7f7]
    "page-wise implementation for the one-dimensional quadratic elements", ""]) %[output:group:4452bca0] %[output:78e6c7f7]
%%
%[text] %[text:anchor:H_26303AAC] ## References
%[text] [\[1\] cane Multiphysics; 2023](https://github.com/andreas-apostolatos/cane)

