%---
%[metadata:view]
%   data: {"layout":"inline","rightPanelPercent":40}
%---
%[control:slider:2abb]
%   data: {"defaultValue":0,"label":"Slider","max":0.3,"min":-2,"run":"AllSections","runOn":"ValueChanged","step":0.1}
